#!/usr/bin/env python3
# sandbox.py -- re-tokenize a corpus kernel hex with an OPTIONAL length override
# hook so we can test proposed instr_length predicates against the real OWN-SHADER
# bytes and prove a residue closes (whole kernel tokenizes with no UNDECODED gap).
# CLEAN-ROOM: every byte is the compiled form of MSL we wrote (OWN-SHADER).
import sys, os
sys.path.insert(0, '/Users/user/cleanroom_gpu/tools/agx-isa')
import isadb

KERNHEX = {
 'k_int64':'',
 'k_uint_arith':'',
 'k_half_arith':'0ca01006671054040100200041010040440067004405020020004101004044001085248400c01884248500082005390410021e038004e7005402000021000100001011000e000000',
 'k_cvt_pack':'7ca01006671054080107200059010040480067004400020720001100004046009704560c03102a5444821714540401000eca1704540001001caa97045408031028d0454229073805290538019f015400031030a81705190538039f015400020008a81705e7005400000721001100009011000e000000',
 'k_mem':'8ca010069f1154000302400411045b1117ff1002000000004b011fff10020000000067005400010820005701004040006700541202852000510100404600670044080184200057010040400009931601810802c01993130a2993130c39131b0ee7005400000821001700001010000e000000',
}

def trim_padding(b):
    while len(b) >= 2 and b[-2:] == b'\x06\x00':
        b = b[:-2]
    return b

OVERRIDE = None  # callable(buf, off) -> int|None ; None => defer to isadb

def L_at(buf, off):
    if OVERRIDE is not None:
        v = OVERRIDE(buf, off)
        if v is not None:
            return v
    return isadb.instr_length(buf, off)

def named_at(buf, off, n):
    L = L_at(buf, off)
    if L is None or off + L > n:
        return None, None
    try:
        rec, _ = isadb.decode_one(buf, off)
        return L, rec['mnemonic']
    except ValueError:
        return L, None

def trace(b, override=None):
    global OVERRIDE
    OVERRIDE = override
    b = trim_padding(b)
    n = len(b); off = 0; undec = 0
    while off < n:
        L, mn = named_at(b, off, n)
        if L is not None:
            tag = mn if mn else '<len%d>' % L
            note = '' if mn else '  (len-only)'
            print(f"{off:4x}: {b[off:off+L].hex(' '):44s} {tag}{note}")
            off += L; continue
        start = off; off += 2
        while off < n:
            L2, mn2 = named_at(b, off, n)
            if mn2 is not None: break
            off += 2
        print(f"{start:4x}: {b[start:off].hex(' '):44s} *** UNDECODED {off-start}B ***")
        undec += off-start
    print(f"  ---- total undecoded bytes: {undec} ----")
    OVERRIDE = None
    return undec

if __name__ == '__main__':
    name = sys.argv[1]
    b = bytes.fromhex(KERNHEX[name])
    trace(b)
